#include "../source/DrumStemExport.h"
#include <iostream>
#include <deque>
static void require(bool ok,const char* text){if(!ok)throw std::runtime_error(text);}
#include "DrumOutputFixture.h"

int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;try{
 const juce::File parent=argc>1?juce::File(juce::String::fromUTF8(argv[1])):juce::File::getSpecialLocation(juce::File::tempDirectory).getChildFile("Tracksmith stem tests");parent.createDirectory();DrumFixture plugin;const auto outputs=DrumStems::outputs(plugin);require(outputs.size()==4&&outputs[1].channels==1&&outputs[2].first==3,"native output-bus mapping");
 const std::vector<MidiNote> notes{{1,36,10,.25,.1,.8f},{2,38,10,.5,.1,.8f}};const auto destination=parent.getNonexistentChildFile("Rendered stems","",false);const auto result=DrumStems::write(plugin,notes,outputs,48000,120,.25,destination,[]{return false;},{});require(result.error.isEmpty()&&!result.cancelled&&result.frames==108000&&result.silent.size()==1,"render succeeds with exact aligned duration and silent-bus report");
 juce::AudioFormatManager formats;formats.registerBasicFormats();auto kick=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(destination.getChildFile("01 - Kick.wav")));auto snare=std::unique_ptr<juce::AudioFormatReader>(formats.createReaderFor(destination.getChildFile("02 - Snare.wav")));require(kick&&snare&&kick->numChannels==2&&snare->numChannels==1&&kick->bitsPerSample==24&&kick->lengthInSamples==snare->lengthInSamples,"separate 24-bit mono/stereo WAVs align");juce::AudioBuffer<float> samples(2,13000);require(kick->read(&samples,0,13000,0,true,true),"read kick WAV");require(std::abs(samples.getSample(0,6000)-.5f)<1.e-6&&std::abs(samples.getSample(1,6000)-.25f)<1.e-6&&std::abs(samples.getSample(0,12000))<1.e-6,"kick routing and latency compensation");samples.clear();require(snare->read(&samples,0,13000,0,true,false)&&std::abs(samples.getSample(0,12000)-.3f)<1.e-6&&std::abs(samples.getSample(0,6000))<1.e-6,"snare routing without kick contamination");require(destination.getChildFile("Stem manifest.json").existsAsFile(),"stem manifest");
 const auto cancelledFolder=parent.getNonexistentChildFile("Cancelled stems","",false);int polls=0;const auto cancelled=DrumStems::write(plugin,notes,outputs,48000,120,0,cancelledFolder,[&]{return ++polls>2;},{});require(cancelled.cancelled&&!cancelledFolder.exists(),"cancel does not publish partial output folder");
 const auto existing=DrumStems::write(plugin,notes,outputs,48000,120,0,destination,[]{return false;},{});require(existing.error.isNotEmpty()&&destination.getChildFile("01 - Kick.wav").existsAsFile(),"existing exports preserved");
 auto invalid=outputs;invalid[0].first=99;const auto badFolder=parent.getNonexistentChildFile("Invalid stems","",false);require(DrumStems::write(plugin,notes,invalid,48000,120,0,badFolder,[]{return false;},{}).error.isNotEmpty()&&!badFolder.exists(),"invalid bus layout rejected safely");
 std::cout<<"PASS: multi-output capture, mono/stereo 24-bit WAVs, shared duration/start, exact MIDI attacks with 128-sample latency compensation, separated kick/snare channels, manifest, silence detection, cancel cleanup, destination preservation and invalid-layout safety.\n";
 }catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}return 0;}
